import { mkdirSync, writeFileSync } from "node:fs";
import { join } from "node:path";
import { randomUUID } from "node:crypto";
import type { CompetitionMarket, DraftManifest, EvidenceCandidate } from "./types.js";

/**
 * Draft writer. One directory per submission under drafts/:
 *   note.md      — the exact 4-part dated note text that would be submitted
 *   data.csv     — compact machine-readable series backing section 3 (written by mathgen)
 *   manifest.json — links, files, stance, idempotency key, submission state
 * The note is a 4-part dated note per the competition guide: dated fact,
 * sources, method, forecast comparison. All key figures are pasted inline so
 * the judge never needs JS rendering (anti-`unverifiable`).
 */

export interface DraftPaths {
  dir: string;
  note: string;
  csv: string;
  manifest: string;
}

export function draftDirFor(runDate: string, topic: string): DraftPaths {
  const dir = join("drafts", `${runDate}-${topic}`);
  return {
    dir,
    note: join(dir, "note.md"),
    csv: join(dir, "data.csv"),
    manifest: join(dir, "manifest.json"),
  };
}

export function composeNote(c: EvidenceCandidate, market: CompetitionMarket): string {
  const impliedPct = (c.analysis.evidenceImpliedYes * 100).toFixed(1);
  const marketPct = (c.marketImpliedYes * 100).toFixed(1);
  const push = c.stance === "yes" ? "up" : "down";
  const lines: string[] = [];
  lines.push(`Evidence note — ${c.asOf.slice(0, 10)} (all times UTC)`);
  lines.push("");
  lines.push(`Market: ${market.question}`);
  lines.push(`Market address: ${market.address} — evidence cutoff ${market.evidenceCutoffAt}`);
  lines.push("");
  lines.push("1) DATED FACT");
  lines.push(c.headline);
  lines.push("");
  lines.push("Key figures, copied from the source content at fetch time (also in data.csv):");
  for (const f of c.figures) lines.push(`- ${f}`);
  lines.push("");
  lines.push("2) SOURCES");
  c.links.forEach((l, i) => {
    lines.push(`- [${i + 1}] ${l.url} — ${c.sourceDescriptions[i] ?? l.label} (${l.lang}, ${l.access})`);
  });
  lines.push(
    "- data.csv (attached) holds the full series/derivation table in machine-readable form; every figure above also appears inline so nothing depends on JS or bot-walled pages.",
  );
  lines.push("");
  lines.push("3) METHOD");
  for (const m of c.analysis.methodLines) lines.push(`- ${m}`);
  lines.push("");
  lines.push("4) FORECAST COMPARISON");
  lines.push(`- Market implied P(yes) at snapshot: ${marketPct}%`);
  lines.push(
    `- This evidence implies P(yes) ≈ ${impliedPct}% (confidence: ${c.analysis.confidence}) — it pushes the ${c.stance.toUpperCase()} side ${push}.`,
  );
  lines.push(
    `- Stance: ${c.stance.toUpperCase()} side only. No evidence is submitted for the opposite side of this market.`,
  );
  return lines.join("\n") + "\n";
}

export function writeDraft(
  c: EvidenceCandidate,
  market: CompetitionMarket,
  mode: "mock" | "live",
  runDate: string,
): DraftPaths {
  const paths = draftDirFor(runDate, c.topic);
  mkdirSync(paths.dir, { recursive: true });
  const manifest: DraftManifest = {
    topic: c.topic,
    marketAddress: c.marketAddress,
    marketQuestion: c.marketQuestion,
    generatedAt: new Date().toISOString(),
    mode,
    asOf: c.asOf,
    stance: c.stance,
    links: c.links.map((l) => l.url),
    files: ["data.csv"],
    factSignature: c.factSignature,
    idempotencyKey: randomUUID(),
    submittedAt: null,
    submissionId: null,
  };
  writeFileSync(paths.note, composeNote(c, market), "utf-8");
  writeFileSync(paths.manifest, JSON.stringify(manifest, null, 2), "utf-8");
  return paths;
}

import { createReadStream } from "node:fs";
import { readFile } from "node:fs/promises";
import type { AgentConfig } from "./config.js";
import type { DraftManifest } from "./types.js";

/**
 * Live submitter. hard-gated: requires mode=live AND LIVE_SUBMIT=1 env AND the
 * --live-submit flag together (resolveConfig). In this build the pipeline never
 * passes --live-submit, so no real submission can occur; the code path exists
 * so Sekar's QA can review exactly what WOULD be sent.
 */

export class SubmitGuardError extends Error {}

export interface SubmitOutcome {
  submissionId: string;
  status: string;
}

export async function submitDraft(cfg: AgentConfig, draftDir: string): Promise<SubmitOutcome> {
  if (!cfg.liveSubmit) {
    throw new SubmitGuardError(
      "submitDraft refused: liveSubmit is off. Set DELPHI_API_ACCESS_KEY, LIVE_SUBMIT=1 and pass --live-submit.",
    );
  }
  const manifest = JSON.parse(await readFile(`${draftDir}/manifest.json`, "utf-8")) as DraftManifest;
  const note = await readFile(`${draftDir}/note.md`, "utf-8");
  const csv = await readFile(`${draftDir}/data.csv`);
  const sdk = await import("@gensyn-ai/gensyn-delphi-sdk");
  const client = new sdk.EvidenceClient({
    baseUrl: cfg.baseUrl,
    apiKey: cfg.delphiApiKey!,
    agentId: cfg.agentId,
    agentHarness: cfg.agentHarness,
    agentModel: cfg.agentModel,
    extraHeaders: {
      // Note + links + one CSV = 3 items, within the per-submission item limit.
      "X-Delphi-Item-Budget": "note+links+1file",
    },
  });
  const { data } = await client.submitEvidence({
    note,
    links: manifest.links,
    files: [new Blob([csv], { type: "text/csv" })],
    marketAddress: manifest.marketAddress,
    idempotencyKey: manifest.idempotencyKey,
  });
  const { data: settled } = await client.waitForSubmission(data.id, { timeoutMs: 10 * 60_000 });
  return { submissionId: settled.id, status: settled.status };
}

/** Form data helper for reference; unused by the guarded path above. */
export async function csvStreamOf(path: string) {
  return createReadStream(path);
}

import { mkdirSync, writeFileSync } from "node:fs";
import { join } from "node:path";
import type { RunReport } from "./types.js";

/**
 * Feedback drafter for the 5x $250 feedback-bounty pool
 * (https://feedback.delphi.fyi). Drafts only in this build: each file holds the
 * exact JSON body + curl command, ready to POST with the API key and wallet
 * once Sekar approves. Never posts automatically.
 */

export interface FeedbackDraft {
  area: "api" | "keys" | "markets" | "judging" | "rewards" | "docs" | "site" | "other";
  title: string;
  text: string;
  marketId?: string;
}

export function feedbackSources(report: RunReport): FeedbackDraft[] {
  const drafts: FeedbackDraft[] = [];

  if (report.marketSkips.some((s) => s.reason.includes("judgment pot empty"))) {
    drafts.push({
      area: "markets",
      title: "markets.json judgment pot in base units is easy to misread",
      text:
        "competition.delphi.fyi/markets.json reports pots as raw 6-decimal base-unit strings " +
        "(\"20000000\" = $20), while /v1 entry-state returns judgementPotRemainingBaseUnits in the same " +
        "units. The markets page shows human-readable dollars. Two different encodings for the same pot " +
        "make it easy to misjudge remaining bounty before researching a market. Could the markets.json " +
        "add a display field (e.g. judgementPotUsdc)?",
    });
  }
  if (report.marketSkips.some((s) => s.reason.includes("canSubmit=false"))) {
    drafts.push({
      area: "markets",
      title: "Entry state gives no market-level hint in markets.json",
      text:
        "Markets visible in markets.json with cutoffs in the future can already be at their " +
        "per-account 3/3 cap (entry-state then reports canSubmit=false with market_submission_cap). " +
        "Agents must call entry-state for every market before shortlisting. A projected " +
        "remainingOnMarket or a visible submission-count field in markets.json would save one " +
        "API call per market per run.",
    });
  }
  drafts.push({
    area: "api",
    title: "Idempotency-Key reuse semantics after a rejected submission",
    text:
      "The guide says submissions cannot be edited or retracted, and the SDK auto-generates an " +
      "Idempotency-Key. It is unclear whether reusing the same key after a `rejected` verdict " +
      "(as opposed to a transport error) is safe, or whether it counts as a new submission against " +
      "the per-market cap. A sentence in /v1/submissions docs would help agents avoid burning a slot.",
  });
  return drafts;
}

export function writeFeedbackDrafts(report: RunReport, wallet: string | undefined): string[] {
  const dir = join("drafts", "feedback");
  mkdirSync(dir, { recursive: true });
  const written: string[] = [];
  feedbackSources(report).forEach((f, i) => {
    const slug = f.title.toLowerCase().replace(/[^a-z0-9]+/g, "-").slice(0, 40);
    const path = join(dir, `${String(i + 1).padStart(2, "0")}-${slug}.md`);
    const body = {
      wallet: wallet ?? "0x<set DELPHI_WALLET to the address your API key was issued to>",
      area: f.area,
      title: f.title,
      text: f.text,
      topic: "agent-competition-evidence-mining",
      ...(f.marketId ? { marketId: f.marketId } : {}),
    };
    writeFileSync(
      path,
      [
        `# Feedback draft: ${f.title}`,
        "",
        "Draft only — review before sending. POST with the same key your API key was issued with.",
        "",
        "```bash",
        `curl -X POST https://feedback.delphi.fyi/v1/feedback \\`,
        `  -H "x-api-key: $DELPHI_API_ACCESS_KEY" \\`,
        `  -H "Content-Type: application/json" \\`,
        `  -H "X-Agent-Id: agent-arena" \\`,
        `  -d '${JSON.stringify(body)}'`,
        "```",
        "",
        "Request body:",
        "",
        "```json",
        JSON.stringify(body, null, 2),
        "```",
        "",
      ].join("\n"),
      "utf-8",
    );
    written.push(path);
  });
  return written;
}

import { mkdirSync, writeFileSync } from "node:fs";
import type { AgentConfig } from "./config.js";
import { createDelphiApi } from "./delphi/client.js";
import { createFirecrawl } from "./firecrawl/client.js";
import { checkEligibility, rankMarkets } from "./filter.js";
import { EvidenceLog } from "./evidence-log.js";
import { gateCandidate } from "./gate.js";
import { SPECS_BY_MARKET } from "./miners/specs.js";
import { assembleCandidate, preSignature, runAnalysis, verifySources } from "./miners/mine.js";
import { writeDraft } from "./draft.js";
import { writeFeedbackDrafts } from "./feedback.js";
import { MOCK_NOW } from "./delphi/fixtures.js";
import type { CompetitionMarket, EvidenceLimits, EvidenceTerms, RunReport } from "./types.js";

const COMPETITION_END = new Date("2026-12-11T17:00:00.000Z");
const EVIDENCE_LOG_PATH = "evidence-log.jsonl";

export interface RunOptions {
  /** Cap on drafts per run (paranoia: never approach the hourly/daily caps in one batch). */
  maxDrafts: number;
}

export async function runPipeline(cfg: AgentConfig, opts: RunOptions): Promise<RunReport> {
  const api = await createDelphiApi(cfg);
  const firecrawl = createFirecrawl(cfg);
  const log = new EvidenceLog(EVIDENCE_LOG_PATH);

  // 1. Limits: do we have submissions left this hour at all?
  const limits: EvidenceLimits = await api.getLimits();
  if (limits.submitsLeftThisHour <= 0) {
    throw new Error(`no submissions left this hour (resets ${limits.hourEndsAt}); nothing to prep`);
  }

  // 2. Terms: in live mode the account must have accepted them before researching.
  const terms: EvidenceTerms = await api.getTerms();
  if (cfg.mode === "live" && !terms.acceptedAt) {
    throw new Error(
      `terms not accepted (${terms.url}). Review, then POST /v1/terms/acceptance {"termsVersion": ${JSON.stringify(terms.version)}}.`,
    );
  }

  // 3. Markets + entry state, then filter and rank.
  const markets = await api.listCompetitionMarkets();
  const now = cfg.mode === "mock" ? new Date(MOCK_NOW) : new Date();
  const pathByAddress = new Map(
    [...SPECS_BY_MARKET.values()].map((s) => [s.marketAddress, s.miningPath] as const),
  );
  const considered: CompetitionMarket[] = [];
  const skips: { address: string; question: string; reason: string }[] = [];
  const eligible: ReturnType<typeof checkEligibility>[] = [];
  for (const m of markets) {
    const entry = await api.getEntryState(m.address);
    const el = checkEligibility(m, entry, now, COMPETITION_END);
    if (el.eligible) eligible.push(el);
    else skips.push({ address: m.address, question: m.question, reason: el.reasons.join("; ") });
  }
  const ranked = rankMarkets(eligible, pathByAddress);

  // 4. Mine specs for eligible markets in ranked order.
  const report: RunReport = {
    runTs: new Date().toISOString(),
    mode: cfg.mode,
    marketsSeen: markets.length,
    marketsEligible: ranked.length,
    marketsConsidered: ranked.map((r) => r.market),
    marketSkips: skips,
    candidatesMined: 0,
    draftsWritten: [],
    duplicatesSkipped: [],
    gateRejects: [],
    draftsSkippedNoSpec: [],
    feedbackDrafts: [],
  };

  const runDate = (cfg.mode === "mock" ? MOCK_NOW : new Date().toISOString()).slice(0, 10);
  const asOf = cfg.mode === "mock" ? MOCK_NOW : new Date().toISOString();

  for (const { market, entry } of ranked) {
    if (report.draftsWritten.length >= opts.maxDrafts) break;
    const spec = SPECS_BY_MARKET.get(market.address);
    if (!spec) {
      report.draftsSkippedNoSpec.push({
        address: market.address,
        question: market.question,
        cutoff: market.evidenceCutoffAt,
      });
      continue;
    }

    // Dedupe before any expensive work: known fact signatures never earn again.
    if (log.hasSignature(preSignature(spec))) {
      report.duplicatesSkipped.push(spec.topic);
      continue;
    }
    // Per-market draft cap: 3 submissions per market (1 if restricted).
    const cap = entry.restricted ? 1 : 3;
    const used = log.draftedCount(market.address);
    if (used >= cap) {
      report.marketSkips.push({
        address: market.address,
        question: market.question,
        reason: `local log already drafted ${used}/${cap} for this market`,
      });
      continue;
    }

    // Anti-unverifiable: scraped sources must still contain the pasted figures.
    const verify = await verifySources(spec, firecrawl);
    if (!verify.ok) {
      report.gateRejects.push({
        topic: spec.topic,
        reasons: verify.failures.map((f) => `unverifiable at ${f.url}: missing ${f.missing.join(", ")}`),
      });
      continue;
    }
    if (verify.warnings.length > 0) {
      // surfaced but not fatal
    }

    report.candidatesMined += 1;
    const paths = { note: "", csv: "", manifest: "", dir: `staging-${spec.topic}` };
    void paths;
    const stub = `staging/${spec.topic}`;
    mkdirSync(stub, { recursive: true });

    // 5. Analysis via the Python math/CSV generator.
    const csvPath = `${stub}/data.csv`;
    const analysis = runAnalysis(spec, csvPath, asOf);
    const candidate = assembleCandidate(spec, market, analysis, asOf);

    // 6. Strict gate.
    const online = await api.listSubmissions({ market: market.address });
    const verdict = gateCandidate(candidate, { market, entry, log, onlineSubmissionCount: online.length });
    if (!verdict.pass) {
      report.gateRejects.push({ topic: spec.topic, reasons: verdict.reasons });
      continue;
    }

    // 7. Draft: note + CSV + manifest in drafts/<date>-<topic>/.
    const draft = writeDraft(candidate, market, cfg.mode, runDate);
    writeFileSync(draft.csv, "" + csvContent(csvPath));
    report.draftsWritten.push(draft.dir);

    // 8. Ledger: stance lock + dedupe apply from now on.
    log.append({
      ts: new Date().toISOString(),
      marketAddress: market.address,
      topic: spec.topic,
      stance: candidate.stance,
      factSignature: candidate.factSignature,
      status: "drafted",
      draftPath: draft.dir,
      submissionId: null,
      note: spec.headline.slice(0, 200),
    });
  }

  // 9. Feedback drafts ($250 bounty pool): note friction observed this run.
  report.feedbackDrafts = writeFeedbackDrafts(report, process.env.DELPHI_WALLET);

  writeReportIndex(report);
  return report;
}

// CSV written by mathgen inside staging; copy helper keeps pipeline simple.
import { readFileSync } from "node:fs";
import { rmSync } from "node:fs";
function csvContent(csvPath: string): string {
  return readFileSync(csvPath, "utf-8");
}

export function writeReportIndex(report: RunReport): void {
  mkdirSync("drafts", { recursive: true });
  writeFileSync(joinDraftsIndex(), JSON.stringify(report, null, 2), "utf-8");
  // Clean staging dirs from this run (gitignored anyway).
  rmSync("staging", { recursive: true, force: true });
}

import { join } from "node:path";
function joinDraftsIndex(): string {
  return join("drafts", "index.json");
}
